def transform(grid):
    n=len(grid)
    out=[[0]*(n*n) for _ in range(n*n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c]:
                for rr in range(n):
                    for cc in range(n):
                        # tile appears to use nonzero color where inner cell is zero
                        if not grid[rr][cc]: out[r*n+rr][c*n+cc]=grid[r][c]
    return out
